<?php foreach($tenants as$t):$st=json_decode((string)($t['settings']??'{}'),true);if(!is_array($st))$st=[];?><form method="post" class="card" style="margin-bottom:14px"><input type="hidden" name="_csrf" value="<?=em_csrf()?>"><input type="hidden" name="tenant_id" value="<?=(int)$t['id']?>"><div class="section-head"><div><span class="eyebrow">EMPRESA #<?=(int)$t['id']?></span><h2><?=Security::e($t['name'])?></h2></div><label class="checkbox"><input type="checkbox" name="enabled"<?=em_checked($st['platform_receipt_ad_enabled']??false)?>> Exibir anúncio</label></div><div class="form-grid"><label>Campanha<input name="campaign" value="<?=Security::e($st['platform_receipt_ad_campaign']??'')?>"></label><label>Título<input name="headline" value="<?=Security::e($st['platform_receipt_ad_headline']??'')?>"></label><label class="span-2">Texto<textarea name="body" maxlength="300"><?=Security::e($st['platform_receipt_ad_body']??'')?></textarea></label><label>Imagem (URL)<input type="url" name="image_url" value="<?=Security::e($st['platform_receipt_ad_image_url']??'')?>"></label><label>Destino/QR do anúncio (URL)<input type="url" name="target_url" value="<?=Security::e($st['platform_receipt_ad_target_url']??'')?>"></label></div><button class="primary" style="margin-top:12px">Salvar publicidade desta empresa</button></form><?php endforeach;?><?php em_footer();
